node - <<'NODE'
const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const m=html.match(/<script id="sim-core">([\s\S]*?)<\/script>/);
fs.writeFileSync('/tmp/sim-core.js',m[1]);
const V=require('/tmp/sim-core.js');
for (const seed of [417, 1884, 5312]) {
  const sim=new V.Simulation({seed,generations:240});
  console.log('\nSEED',seed,'initial', JSON.stringify(sim.latest.prey), sim.latest.predators, sim.latest.plants.toFixed(1));
  const marks=[20,40,60,80,90,100,120,130,150,170,190,210,240];
  let prev=0;
  while(sim.generation<240){
    sim.step();
    if(marks.includes(sim.generation)){
      const l=sim.latest;
      console.log(`${sim.generation}g prey ${String(l.prey).padStart(3)} pred ${String(l.predators).padStart(2)} flora ${l.plants.toFixed(1).padStart(4)}% births ${sim.totals.births} events ${sim.eventLog.length} genesPrey`, Object.fromEntries(Object.entries(l.traits.prey).map(([k,v])=>[k, +(v.mean??0).toFixed(2)+'/'+(v.sd??0).toFixed(2)])));
    }
  }
  console.log('events',sim.eventLog.map(e=>`${e.generation}:${e.type}(${e.detail})`).join(' | '));
}
