from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.errors=[]; self.ids=set(); self.dups=set()
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if tag not in ('meta','link','br','hr','img','input','source','area','base','col','embed','param','track','wbr'):
            self.stack.append(tag)
        if 'id' in attrs:
            if attrs['id'] in self.ids: self.dups.add(attrs['id'])
            self.ids.add(attrs['id'])
    def handle_endtag(self, tag):
        if tag in ('meta','link','br','hr','img','input','source','area','base','col','embed','param','track','wbr'): return
        if tag in self.stack:
            # pop until tag; flag mismatched
            if self.stack[-1]!=tag:
                self.errors.append(('mismatch', tag, list(self.stack[-5:])))
            while self.stack and self.stack[-1]!=tag:
                self.stack.pop()
            if self.stack: self.stack.pop()
        else:
            self.errors.append(('unopened', tag))
p=P(); p.feed(Path('index.html').read_text())
print('stack',p.stack)
print('errors',p.errors[:20])
print('dups',p.dups)
